export const createCanvasResizeObserver = (element, canvas, onResize) => {
    let resizeObserver = null;
    let timeoutId = null;
    const debouncedResize = () => {
        if (timeoutId) {
            clearTimeout(timeoutId);
        }
        timeoutId = window.setTimeout(() => {
            onResize();
            timeoutId = null;
        }, 100);
    };
    if (typeof ResizeObserver !== 'undefined') {
        resizeObserver = new ResizeObserver((entries) => {
            for (const entry of entries) {
                const { width, height } = entry.contentRect;
                const currentWidth = parseFloat(canvas.style.width || '0');
                const currentHeight = parseFloat(canvas.style.height || '0');
                if (Math.abs(width - currentWidth) > 1 || Math.abs(height - currentHeight) > 1) {
                    debouncedResize();
                }
            }
        });
        resizeObserver.observe(element);
    }
    else {
        window.addEventListener('resize', debouncedResize);
    }
    return () => {
        if (timeoutId) {
            clearTimeout(timeoutId);
        }
        if (resizeObserver) {
            resizeObserver.disconnect();
        }
        else {
            window.removeEventListener('resize', debouncedResize);
        }
    };
};
